  var app=RuntimeEnvironment.getApplication();for(String name:new String[]{"Телефон","Ноутбук","Планшет"}){String key=SshKeys.generate().getString(SshKeys.PUBLIC);ServerDevices.add(app,key);ServerDevices.rename(app,key,name);}var preferences=app.getSharedPreferences(EmbeddedServerService.PREFS,0).getAll();var appearance=app.getSharedPreferences(ServerConfig.PREFS,0).getAll();
