   ReflectionHelpers.callInstanceMethod(home,"render",ReflectionHelpers.ClassParameter.from(ServerTelemetry.class,new ServerTelemetry(35,137L*1073741824,256L*1073741824,1080000,1)),ReflectionHelpers.ClassParameter.from(List.class,ServerDevices.list(app)),ReflectionHelpers.ClassParameter.from(Set.class,Collections.emptySet()),ReflectionHelpers.ClassParameter.from(List.class,Collections.emptyList()));
   root.measure(exact(411),exact(890));root.layout(0,0,411,890);TextView count=root.findViewById(R.id.serverPanelDeviceCount),title=ReflectionHelpers.getField(home,"deviceTitle");assertEquals("3 из 7",count.getText().toString());assertEquals("Устройства с доступом",title.getText().toString());assertTrue(count.getLeft()>=title.getRight());assertEquals(((View)count.getParent()).getWidth(),count.getRight());assertEquals(preferences,app.getSharedPreferences(EmbeddedServerService.PREFS,0).getAll());assertEquals(appearance,app.getSharedPreferences(ServerConfig.PREFS,0).getAll());
