 private void capture(Activity a,String name,int w,int h)throws Exception{View root=((ViewGroup)a.findViewById(android.R.id.content)).getChildAt(0);root.measure(exact(w),exact(h));root.layout(0,0,w,h);Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);root.draw(new Canvas(b));File dir=new File("build/ui-previews/reference-r4-20261025");dir.mkdirs();try(var out=new FileOutputStream(new File(dir,name+".png"))){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}b.recycle();}
 private static int exact(int size){return View.MeasureSpec.makeMeasureSpec(size,View.MeasureSpec.EXACTLY);}
